/**
 * JSON schema validation error for a specified input.
 */ export class ValidationErrorObject extends Error {
    #details;
    #path;
    constructor(errorObject){
        super(errorObject.message ?? `Validation failed for ${errorObject.keyword}`);
        this.#details = errorObject;
        this.#path = errorObject.instancePath.split('/').filter((part)=>part !== '');
    }
    get details() {
        return this.#details;
    }
    get path() {
        return this.#path;
    }
}
/**
 * Aggregate of errors raised when validating a `data` input against a JSON `schema`.
 */ export class ValidationError extends AggregateError {
    #schema;
    #value;
    constructor(schema, value, errorObjects){
        const schemaInfo = schema.$id ?? schema.type;
        super((errorObjects ?? []).map((err)=>new ValidationErrorObject(err)), schemaInfo ? `Validation failed for schema ${schemaInfo}` : 'Schema validation failed');
        this.#schema = schema;
        this.#value = value;
    }
    get issues() {
        return this.errors;
    }
    get schema() {
        return this.#schema;
    }
    get value() {
        return this.#value;
    }
}
